// Generates lib/generated/*.ts from app/prototypes/*/metadata.json.
// Runs automatically before dev, build, lint and typecheck. Do not edit the output.
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const protoDir = path.join(root, "app/prototypes");
const outDir = path.join(root, "lib/generated");
const has = (p) => fs.existsSync(path.join(root, "public", p));

const slugs = fs
  .readdirSync(protoDir, { withFileTypes: true })
  .filter((d) => d.isDirectory() && !d.name.startsWith("[") && !d.name.startsWith("_"))
  .map((d) => d.name)
  .filter((slug) => {
    const ok = ["page.tsx", "metadata.json", "HOW_IT_WORKS.md"].every((f) =>
      fs.existsSync(path.join(protoDir, slug, f)),
    );
    if (!ok) console.warn(`[gen-registry] skipping ${slug}: needs page.tsx, metadata.json, HOW_IT_WORKS.md`);
    return ok;
  })
  .sort();

const entries = slugs.map((slug) => {
  const meta = JSON.parse(fs.readFileSync(path.join(protoDir, slug, "metadata.json"), "utf8"));
  for (const key of ["title", "description", "createdAt", "updatedAt"]) {
    if (typeof meta[key] !== "string") throw new Error(`[gen-registry] ${slug}/metadata.json: "${key}" must be a string`);
  }
  return {
    slug,
    title: meta.title,
    description: meta.description,
    tags: Array.isArray(meta.tags) ? meta.tags : [],
    createdAt: meta.createdAt,
    updatedAt: meta.updatedAt,
    hidden: meta.hidden === true,
    public: meta.public === true,
    thumbnail: {
      light: has(`thumbnails/${slug}-light.png`) ? `/thumbnails/${slug}-light.png` : null,
      dark: has(`thumbnails/${slug}-dark.png`) ? `/thumbnails/${slug}-dark.png` : null,
    },
    og: {
      image: has(`og/${slug}.png`) ? `/og/${slug}.png` : null,
      video: has(`og/${slug}.mp4`) ? `/og/${slug}.mp4` : null,
    },
  };
});

fs.mkdirSync(outDir, { recursive: true });
const header = "// AUTO-GENERATED by scripts/gen-registry.mjs. Do not edit.\n";
write(
  "prototypes.ts",
  `${header}import type { PrototypeMeta } from "@/lib/prototype-types";\n\nexport const prototypes: PrototypeMeta[] = ${JSON.stringify(entries, null, 2)};\n`,
);
write(
  "components.ts",
  `${header}import type { ComponentType } from "react";\n\nexport const prototypeComponents: Record<string, () => Promise<{ default: ComponentType }>> = {\n${slugs
    .map((s) => `  ${JSON.stringify(s)}: () => import("@/app/prototypes/${s}/page"),`)
    .join("\n")}\n};\n`,
);
console.log(`[gen-registry] ${slugs.length} prototype(s): ${slugs.join(", ") || "none"}`);

function write(name, content) {
  const file = path.join(outDir, name);
  if (fs.existsSync(file) && fs.readFileSync(file, "utf8") === content) return;
  fs.writeFileSync(file, content);
}
